package com.campus.service;import com.campus.common.Paging;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import java.util.*;@Service public class AdvertisementService{final JdbcTemplate db;AdvertisementService(JdbcTemplate d){db=d;}public List<Map<String,Object>> active(String placement){String w=placement==null?"":" AND placement=?";return db.queryForList("SELECT * FROM advertisement WHERE status='ACTIVE' AND start_at<=NOW() AND end_at>NOW()"+w+" ORDER BY id DESC",placement==null?new Object[]{}:new Object[]{placement});}public void impression(long id){db.update("UPDATE advertisement SET impressions=impressions+1 WHERE id=? AND status='ACTIVE'",id);}public void click(long id){db.update("UPDATE advertisement SET clicks=clicks+1 WHERE id=? AND status='ACTIVE'",id);}public Map<String,Object> list(int page,int size){var p=new Paging(page,size);return Map.of("records",db.queryForList("SELECT * FROM advertisement ORDER BY created_at DESC,id DESC "+p.limit()),"total",db.queryForObject("SELECT COUNT(*) FROM advertisement",Long.class),"page",p.page(),"size",p.size());}public long create(long uid,Map<String,Object>x){String title=String.valueOf(x.get("title")),merchant=String.valueOf(x.get("merchantName")),placement=String.valueOf(x.get("placement"));if(title.isBlank()||merchant.isBlank()||!Set.of("HOME_BANNER","SIDEBAR","CATEGORY_TOP","DETAIL_RECOMMEND").contains(placement))throw new IllegalArgumentException("广告信息无效");db.update("INSERT INTO advertisement(merchant_name,title,image_url,target_url,placement,amount,start_at,end_at,created_by) VALUES(?,?,?,?,?,?,?,?,?)",merchant,title,x.get("imageUrl"),x.get("targetUrl"),placement,x.getOrDefault("amount",0),x.get("startAt"),x.get("endAt"),uid);return db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);}public Map<String,Object> stats(){return db.queryForMap("SELECT COUNT(*) ads,COALESCE(SUM(amount),0) revenue,COALESCE(SUM(impressions),0) impressions,COALESCE(SUM(clicks),0) clicks FROM advertisement");}public void status(long id,String status){if(!Set.of("ACTIVE","PAUSED","REJECTED").contains(status))throw new IllegalArgumentException("广告状态无效");db.update("UPDATE advertisement SET status=? WHERE id=?",status,id);}}
